const PAGE_HTML_BASE64 = "";
const PAGE_HTML = new TextDecoder().decode(Uint8Array.from(atob(PAGE_HTML_BASE64), (char) => char.charCodeAt(0)));
const GLO_RESULT_API = "https://www.glo.or.th/api/checking/getLotteryResult";
const GITHUB_PAGES_ORIGIN = "https://jamroen1972-ux.github.io";

function lotteryCorsHeaders(request) {
  const origin = request.headers.get("Origin");
  return origin === GITHUB_PAGES_ORIGIN
    ? { "access-control-allow-origin": origin, "vary": "Origin" }
    : {};
}

function jsonResponse(payload, status = 200, extraHeaders = {}) {
  return new Response(JSON.stringify(payload), {
    status,
    headers: { "content-type": "application/json; charset=utf-8", "cache-control": "no-store", ...extraHeaders },
  });
}

export default {
  async fetch(request) {
    const url = new URL(request.url);
    if (url.pathname === "/api/travel-subdistricts") {
      if (request.method !== "GET") return jsonResponse({ error: "Method not allowed" }, 405);
      try {
        const [subResponse, districtResponse] = await Promise.all([
          fetch("https://api.openadmindata.org/api/v1/th/subdistrict.json", { headers: { accept: "application/json" } }),
          fetch("https://api.openadmindata.org/api/v1/th/district.json", { headers: { accept: "application/json" } }),
        ]);
        if (!subResponse.ok || !districtResponse.ok) throw new Error("Administrative data unavailable");
        const [subPayload, districtPayload] = await Promise.all([subResponse.json(), districtResponse.json()]);
        const rows = (payload, level) => {
          const candidates = [payload, payload?.data, payload?.entities, payload?.result, payload?.results, payload?.items, payload?.records,
            payload?.data?.[level], payload?.data?.entities, payload?.data?.items, payload?.data?.results, payload?.data?.records];
          return candidates.find(Array.isArray) || [];
        };
        const districts = rows(districtPayload, "district");
        const byId = new Map(districts.map(item => [String(item.id ?? item.code ?? item.district_id), item]));
        const local = item => item?.name_local || item?.name?.local || item?.name_th || item?.tambon_t || item?.amphoe_t || "";
        const subdistricts = rows(subPayload, "subdistrict").map(item => {
          const parent = byId.get(String(item.parent_id ?? item.district_id ?? item.am_id));
          const ancestors = Array.isArray(item.ancestors) ? item.ancestors.map(local).filter(Boolean) : [];
          const parentAncestors = Array.isArray(parent?.ancestors) ? parent.ancestors.map(local).filter(Boolean) : [];
          const district = local(parent) || item.district_name_local || item.district_name_th || item.parent_name_local || item.amphoe_t || ancestors.at(-1) || "";
          const province = parent?.parent_name_local || parent?.province_name_local || item.province_name_local || item.province_name_th || item.changwat_t || parentAncestors.at(-1) || ancestors.at(-2) || "";
          return { name: local(item), district, province };
        }).filter(item => item.name && item.district && item.province);
        if (!subdistricts.length) throw new Error("No complete subdistrict rows");
        return new Response(JSON.stringify({ subdistricts }), {
          headers: { "content-type": "application/json; charset=utf-8", "cache-control": "public, max-age=3600" },
        });
      } catch {
        return jsonResponse({ error: "Unable to load Thailand subdistrict data" }, 502);
      }
    }
    if (url.pathname === "/api/glo-result") {
      const cors = lotteryCorsHeaders(request);
      if (request.method === "OPTIONS" && cors["access-control-allow-origin"]) {
        return new Response(null, {
          status: 204,
          headers: {
            ...cors,
            "access-control-allow-methods": "POST, OPTIONS",
            "access-control-allow-headers": "content-type",
            "access-control-max-age": "86400",
          },
        });
      }
      if (request.method !== "POST") return jsonResponse({ error: "Method not allowed" }, 405, cors);
      let draw;
      try { draw = await request.json(); } catch { return jsonResponse({ error: "Invalid JSON" }, 400, cors); }
      const date = String(draw?.date ?? "");
      const month = String(draw?.month ?? "");
      const year = String(draw?.year ?? "");
      if (!/^(0[1-9]|[12][0-9]|3[01])$/.test(date) || !/^(0[1-9]|1[0-2])$/.test(month) || !/^(19|20|21)[0-9]{2}$/.test(year)) {
        return jsonResponse({ error: "Invalid draw date" }, 400, cors);
      }
      try {
        const upstream = await fetch(GLO_RESULT_API, {
          method: "POST",
          headers: { "content-type": "application/json", accept: "application/json" },
          body: JSON.stringify({ date, month, year }),
        });
        const text = await upstream.text();
        return new Response(text, {
          status: upstream.status,
          headers: {
            ...cors,
            "content-type": upstream.headers.get("content-type") || "application/json; charset=utf-8",
            "cache-control": "no-store",
          },
        });
      } catch {
        return jsonResponse({ error: "Unable to reach the Government Lottery Office" }, 502, cors);
      }
    }
    if (url.pathname !== "/" && url.pathname !== "/index.html") return new Response("Not found", { status: 404 });
    return new Response(PAGE_HTML, { headers: { "content-type": "text/html; charset=utf-8", "cache-control": "no-cache" } });
  },
};
